ALTER TABLE public.messages ADD COLUMN IF NOT EXISTS media_type text, ADD COLUMN IF NOT EXISTS file_name text;
CREATE POLICY "Admins read chat media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'chat-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins upload chat media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'chat-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete chat media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'chat-media' AND public.has_role(auth.uid(), 'admin'));